15	func TestScaffoldSearchSubagent_CreatesManagedFiles(t *testing.T) {
16		testCases := []struct {
17			name        string
18			scaffoldFn  func() (searchSubagentScaffoldResult, error)
19			relPath     string
20			wantSnippet string
21		}{
22			{
23				name: "claude",
24				scaffoldFn: func() (searchSubagentScaffoldResult, error) {
25					return scaffoldSearchSubagent(context.Background(), claudecode.NewClaudeCodeAgent())
26				},
27				relPath:     filepath.Join(".claude", "agents", "search.md"),
28				wantSnippet: "tools: Bash",
29			},
30			{
31				name: "codex",
32				scaffoldFn: func() (searchSubagentScaffoldResult, error) {
33					return scaffoldSearchSubagent(context.Background(), codex.NewCodexAgent())
34				},
35				relPath:     filepath.Join(".codex", "agents", "search.toml"),
36				wantSnippet: `sandbox_mode = "read-only"`,
37			},
38			{
39				name: "gemini",
40				scaffoldFn: func() (searchSubagentScaffoldResult, error) {
41					return scaffoldSearchSubagent(context.Background(), geminicli.NewGeminiCLIAgent())
42				},
43				relPath:     filepath.Join(".gemini", "agents", "search.md"),
44				wantSnippet: "- run_shell_command",
45			},
46		}
47	
48		for _, tc := range testCases {
49			t.Run(tc.name, func(t *testing.T) {
50				tmpDir := setupTestDir(t)
51	
52				result, err := tc.scaffoldFn()
53				if err != nil {
54					t.Fatalf("scaffoldSearchSubagent() error = %v", err)
55				}
56				if result.Status != searchSubagentCreated {
57					t.Fatalf("scaffoldSearchSubagent() status = %q, want %q", result.Status, searchSubagentCreated)
58				}
59				if result.RelPath != tc.relPath {
60					t.Fatalf("scaffoldSearchSubagent() relPath = %q, want %q", result.RelPath, tc.relPath)
61				}
62	
63				data, err := os.ReadFile(filepath.Join(tmpDir, tc.relPath))
64				if err != nil {
65					t.Fatalf("failed to read scaffolded file: %v", err)
66				}
67				content := string(data)
68				if !strings.Contains(content, entireManagedSearchSubagentMarker) {
69					t.Fatal("scaffolded file should contain Entire-managed marker")
70				}
71				assertStrictJSONSearchInstructions(t, content)
72				if !strings.Contains(content, tc.wantSnippet) {
73					t.Fatalf("scaffolded file missing expected snippet %q", tc.wantSnippet)
74				}
75			})
76		}
77	}
