96	func TestScaffoldSearchSubagent_UpdatesManagedFile(t *testing.T) {
97		tmpDir := setupTestDir(t)
98	
99		ag := claudecode.NewClaudeCodeAgent()
100		relPath, _, ok := searchSubagentTemplate(ag.Name())
101		if !ok {
102			t.Fatal("searchSubagentTemplate() unexpectedly unsupported for claude")
103		}
104	
105		targetPath := filepath.Join(tmpDir, relPath)
106		if err := os.MkdirAll(filepath.Dir(targetPath), 0o755); err != nil {
107			t.Fatalf("failed to create target dir: %v", err)
108		}
109		oldContent := "<!-- " + entireManagedSearchSubagentMarker + " -->\noutdated\n"
110		if err := os.WriteFile(targetPath, []byte(oldContent), 0o644); err != nil {
111			t.Fatalf("failed to write old managed content: %v", err)
112		}
113	
114		result, err := scaffoldSearchSubagent(context.Background(), ag)
115		if err != nil {
116			t.Fatalf("scaffoldSearchSubagent() error = %v", err)
117		}
118		if result.Status != searchSubagentUpdated {
119			t.Fatalf("scaffoldSearchSubagent() status = %q, want %q", result.Status, searchSubagentUpdated)
120		}
121	
122		data, err := os.ReadFile(targetPath)
123		if err != nil {
124			t.Fatalf("failed to read updated content: %v", err)
125		}
126		if !strings.Contains(string(data), "tools: Bash") {
127			t.Fatal("updated managed file should contain the current template")
128		}
129		assertStrictJSONSearchInstructions(t, string(data))
130	}
